#!/usr/bin/env python3
"""
Unified Product Category Taxonomy Builder
Processes category data from Amazon, Facebook, and Google Shopping to create a unified taxonomy
"""

import pandas as pd
import numpy as np
from collections import defaultdict, Counter
import re
from typing import List, Dict, Set, Tuple
import csv


class CategoryNormalizer:
    """Normalizes and standardizes category names"""

    @staticmethod
    def normalize(text: str) -> str:
        """Normalize category text"""
        if pd.isna(text):
            return ""

        text = str(text).strip()
        # Remove quotes
        text = text.strip('"\'')
        # Remove extra whitespace
        text = re.sub(r'\s+', ' ', text)
        # Standardize case (title case)
        text = text.title()
        # Fix common abbreviations
        replacements = {
            ' & ': ' | ',
            ' And ': ' | ',
            ',': ' |',
        }
        for old, new in replacements.items():
            text = text.replace(old, new)

        return text.strip()

    @staticmethod
    def extract_keywords(text: str) -> Set[str]:
        """Extract keywords from category name"""
        text = text.lower()
        # Remove common stop words
        stop_words = {'and', 'or', 'the', 'a', 'an', 'for', 'with', 'in', 'on', 'at', 'to', 'from'}
        words = re.findall(r'\w+', text)
        return {w for w in words if w not in stop_words and len(w) > 2}

    @staticmethod
    def word_overlap(text1: str, text2: str) -> float:
        """Calculate word overlap percentage between two texts"""
        words1 = CategoryNormalizer.extract_keywords(text1)
        words2 = CategoryNormalizer.extract_keywords(text2)

        if not words1 or not words2:
            return 0.0

        intersection = len(words1 & words2)
        union = len(words1 | words2)

        return intersection / union if union > 0 else 0.0


class TaxonomyBuilder:
    """Builds unified taxonomy from multiple sources"""

    def __init__(self):
        self.normalizer = CategoryNormalizer()
        self.category_tree = defaultdict(lambda: defaultdict(set))
        self.category_counts = defaultdict(int)
        self.category_sources = defaultdict(lambda: defaultdict(int))

    def parse_category_path(self, path: str, separator: str = '>') -> List[str]:
        """Parse category path into levels"""
        if pd.isna(path):
            return []

        parts = [p.strip() for p in str(path).split(separator)]
        normalized = [self.normalizer.normalize(p) for p in parts if p.strip()]
        return normalized

    def add_category_path(self, path_parts: List[str], source: str):
        """Add a category path to the tree"""
        if not path_parts:
            return

        # Add to counts
        for i, part in enumerate(path_parts):
            level_key = f"L{i}"
            self.category_counts[f"{level_key}:{part}"] += 1
            self.category_sources[f"{level_key}:{part}"][source] += 1

            if i > 0:
                parent = path_parts[i-1]
                self.category_tree[f"L{i-1}:{parent}"][part] = self.category_tree.get(f"L{i}:{part}", {})

    def load_data(self, amazon_file: str, fb_file: str, google_file: str):
        """Load and process all data files"""
        print("Loading Amazon categories...")
        df_amazon = pd.read_csv(amazon_file)
        for _, row in df_amazon.iterrows():
            parts = self.parse_category_path(row['category_path'])
            self.add_category_path(parts, 'amazon')

        print("Loading Facebook categories...")
        df_fb = pd.read_csv(fb_file)
        for _, row in df_fb.iterrows():
            parts = self.parse_category_path(row['category_path'])
            self.add_category_path(parts, 'facebook')

        print("Loading Google Shopping categories...")
        df_google = pd.read_csv(google_file)
        for _, row in df_google.iterrows():
            parts = self.parse_category_path(row['category_path'])
            self.add_category_path(parts, 'google')

        print(f"Total unique category nodes: {len(self.category_counts)}")
        return df_amazon, df_fb, df_google

    def cluster_similar_categories(self, categories: List[str], max_clusters: int = 20) -> Dict[str, List[str]]:
        """Cluster similar categories together"""
        if len(categories) <= max_clusters:
            return {cat: [cat] for cat in categories}

        # Sort by frequency
        sorted_cats = sorted(categories, key=lambda x: self.category_counts.get(x, 0), reverse=True)

        clusters = {}
        assigned = set()

        for cat in sorted_cats:
            if cat in assigned:
                continue

            # This category becomes a cluster representative
            cluster_members = [cat]
            assigned.add(cat)

            # Find similar categories
            for other_cat in sorted_cats:
                if other_cat in assigned:
                    continue

                # Check similarity
                overlap = self.normalizer.word_overlap(cat, other_cat)
                if overlap > 0.6:  # High similarity threshold
                    cluster_members.append(other_cat)
                    assigned.add(other_cat)

            clusters[cat] = cluster_members

            if len(clusters) >= max_clusters:
                break

        # Assign remaining categories to closest cluster
        for cat in sorted_cats:
            if cat not in assigned:
                best_cluster = None
                best_overlap = 0

                for cluster_rep in clusters.keys():
                    overlap = self.normalizer.word_overlap(cat, cluster_rep)
                    if overlap > best_overlap:
                        best_overlap = overlap
                        best_cluster = cluster_rep

                if best_cluster:
                    clusters[best_cluster].append(cat)
                else:
                    clusters[cat] = [cat]

        return clusters

    def generate_representative_name(self, category_names: List[str], parent_name: str = "") -> str:
        """Generate a representative name for a cluster of categories"""
        if len(category_names) == 1:
            name = category_names[0]
        else:
            # Extract common keywords
            all_keywords = []
            for cat in category_names:
                all_keywords.extend(self.normalizer.extract_keywords(cat))

            # Count keyword frequency
            keyword_counts = Counter(all_keywords)

            # Select top keywords
            top_keywords = [k for k, _ in keyword_counts.most_common(5)]

            # Try to build a representative name
            if top_keywords:
                name = ' | '.join(top_keywords[:5])
            else:
                # Fallback to most frequent category
                name = max(category_names, key=lambda x: self.category_counts.get(x, 0))

        # Ensure no overlap with parent
        if parent_name:
            parent_keywords = self.normalizer.extract_keywords(parent_name)
            name_keywords = self.normalizer.extract_keywords(name)

            # Remove parent keywords
            unique_keywords = [k for k in name.split(' | ') if k.lower() not in parent_keywords]
            if unique_keywords:
                name = ' | '.join(unique_keywords[:5])

        # Limit to 5 words
        parts = name.split(' | ')
        if len(parts) > 5:
            name = ' | '.join(parts[:5])

        return name.title()

    def build_unified_taxonomy(self) -> Dict:
        """Build 5-level unified taxonomy"""
        print("\nBuilding unified taxonomy...")

        unified_tree = {}

        # Level 1: Top-level categories (10-20 broad categories)
        level1_cats = [cat.split(':', 1)[1] for cat in self.category_counts.keys() if cat.startswith('L0:')]
        print(f"Found {len(level1_cats)} level 1 categories before clustering")

        level1_clusters = self.cluster_similar_categories(level1_cats, max_clusters=15)
        print(f"Created {len(level1_clusters)} level 1 clusters")

        for l1_rep, l1_members in level1_clusters.items():
            l1_name = self.generate_representative_name(l1_members)
            unified_tree[l1_name] = {'members': l1_members, 'children': {}}

            # Level 2: Subcategories under each L1
            level2_cats = set()
            for l1_member in l1_members:
                # Find all L2 categories that appear after this L1
                for cat_key in self.category_counts.keys():
                    if cat_key.startswith('L1:'):
                        level2_cats.add(cat_key.split(':', 1)[1])

            if level2_cats:
                level2_clusters = self.cluster_similar_categories(list(level2_cats), max_clusters=20)

                for l2_rep, l2_members in level2_clusters.items():
                    l2_name = self.generate_representative_name(l2_members, l1_name)

                    # Ensure distinct from siblings
                    sibling_names = list(unified_tree[l1_name]['children'].keys())
                    is_distinct = True
                    for sibling in sibling_names:
                        if self.normalizer.word_overlap(l2_name, sibling) > 0.3:
                            is_distinct = False
                            break

                    if not is_distinct:
                        # Modify name to be more distinct
                        l2_name = l2_rep

                    unified_tree[l1_name]['children'][l2_name] = {'members': l2_members, 'children': {}}

                    # Level 3
                    level3_cats = set()
                    for cat_key in self.category_counts.keys():
                        if cat_key.startswith('L2:'):
                            level3_cats.add(cat_key.split(':', 1)[1])

                    if level3_cats:
                        level3_clusters = self.cluster_similar_categories(list(level3_cats), max_clusters=20)

                        for l3_rep, l3_members in list(level3_clusters.items())[:20]:
                            l3_name = self.generate_representative_name(l3_members, l2_name)
                            unified_tree[l1_name]['children'][l2_name]['children'][l3_name] = {
                                'members': l3_members, 'children': {}
                            }

                            # Level 4
                            level4_cats = set()
                            for cat_key in self.category_counts.keys():
                                if cat_key.startswith('L3:'):
                                    level4_cats.add(cat_key.split(':', 1)[1])

                            if level4_cats:
                                level4_clusters = self.cluster_similar_categories(list(level4_cats), max_clusters=20)

                                for l4_rep, l4_members in list(level4_clusters.items())[:20]:
                                    l4_name = self.generate_representative_name(l4_members, l3_name)
                                    unified_tree[l1_name]['children'][l2_name]['children'][l3_name]['children'][l4_name] = {
                                        'members': l4_members, 'children': {}
                                    }

                                    # Level 5
                                    level5_cats = set()
                                    for cat_key in self.category_counts.keys():
                                        if cat_key.startswith('L4:'):
                                            level5_cats.add(cat_key.split(':', 1)[1])

                                    if level5_cats:
                                        level5_clusters = self.cluster_similar_categories(list(level5_cats), max_clusters=20)

                                        for l5_rep, l5_members in list(level5_clusters.items())[:20]:
                                            l5_name = self.generate_representative_name(l5_members, l4_name)
                                            unified_tree[l1_name]['children'][l2_name]['children'][l3_name]['children'][l4_name]['children'][l5_name] = {
                                                'members': l5_members
                                            }

        return unified_tree

    def map_original_to_unified(self, df: pd.DataFrame, source: str, unified_tree: Dict) -> List[Dict]:
        """Map original categories to unified taxonomy"""
        results = []

        for _, row in df.iterrows():
            original_path = row['category_path']
            parts = self.parse_category_path(original_path)

            if not parts:
                continue

            # Find best match in unified tree
            unified_levels = ['', '', '', '', '']

            # Match L1
            best_l1 = self.find_best_match(parts[0] if len(parts) > 0 else '', unified_tree)
            if best_l1:
                unified_levels[0] = best_l1

                # Match L2
                if len(parts) > 1 and best_l1 in unified_tree:
                    best_l2 = self.find_best_match(parts[1], unified_tree[best_l1].get('children', {}))
                    if best_l2:
                        unified_levels[1] = best_l2

                        # Match L3
                        if len(parts) > 2 and best_l2 in unified_tree[best_l1]['children']:
                            best_l3 = self.find_best_match(parts[2], unified_tree[best_l1]['children'][best_l2].get('children', {}))
                            if best_l3:
                                unified_levels[2] = best_l3

                                # Match L4
                                if len(parts) > 3 and best_l3 in unified_tree[best_l1]['children'][best_l2]['children']:
                                    best_l4 = self.find_best_match(parts[3], unified_tree[best_l1]['children'][best_l2]['children'][best_l3].get('children', {}))
                                    if best_l4:
                                        unified_levels[3] = best_l4

                                        # Match L5
                                        if len(parts) > 4 and best_l4 in unified_tree[best_l1]['children'][best_l2]['children'][best_l3]['children']:
                                            best_l5 = self.find_best_match(parts[4], unified_tree[best_l1]['children'][best_l2]['children'][best_l3]['children'][best_l4].get('children', {}))
                                            if best_l5:
                                                unified_levels[4] = best_l5

            depth = sum(1 for level in unified_levels if level)

            results.append({
                'source': source,
                'category_path': original_path,
                'depth': depth,
                'unified_level_1': unified_levels[0],
                'unified_level_2': unified_levels[1],
                'unified_level_3': unified_levels[2],
                'unified_level_4': unified_levels[3],
                'unified_level_5': unified_levels[4]
            })

        return results

    def find_best_match(self, category: str, candidates: Dict) -> str:
        """Find best matching category in candidates"""
        if not candidates:
            return ''

        if not category:
            return list(candidates.keys())[0] if candidates else ''

        best_match = None
        best_score = 0

        for candidate_name, candidate_data in candidates.items():
            # Check if category is in members
            if isinstance(candidate_data, dict) and 'members' in candidate_data:
                if category in candidate_data['members']:
                    return candidate_name

                # Check similarity with members
                for member in candidate_data['members']:
                    score = self.normalizer.word_overlap(category, member)
                    if score > best_score:
                        best_score = score
                        best_match = candidate_name

            # Also check similarity with candidate name itself
            score = self.normalizer.word_overlap(category, candidate_name)
            if score > best_score:
                best_score = score
                best_match = candidate_name

        return best_match if best_match else (list(candidates.keys())[0] if candidates else '')

    def extract_all_paths(self, tree: Dict, current_path: List[str] = None) -> List[List[str]]:
        """Extract all paths from tree"""
        if current_path is None:
            current_path = []

        paths = []

        for key, value in tree.items():
            new_path = current_path + [key]

            if isinstance(value, dict):
                if 'children' in value and value['children']:
                    # Recurse into children
                    paths.extend(self.extract_all_paths(value['children'], new_path))
                else:
                    # Leaf node
                    paths.append(new_path)
            else:
                paths.append(new_path)

        return paths


def main():
    print("=== Unified Product Category Taxonomy Builder ===\n")

    builder = TaxonomyBuilder()

    # Load data
    df_amazon, df_fb, df_google = builder.load_data(
        '/root/data/amazon_product_categories.csv',
        '/root/data/fb_product_categories.csv',
        '/root/data/google_shopping_product_categories.csv'
    )

    # Build unified taxonomy
    unified_tree = builder.build_unified_taxonomy()

    print(f"\nUnified taxonomy created with {len(unified_tree)} top-level categories")

    # Map original categories to unified
    print("\nMapping Amazon categories...")
    amazon_mapped = builder.map_original_to_unified(df_amazon, 'amazon', unified_tree)

    print("Mapping Facebook categories...")
    fb_mapped = builder.map_original_to_unified(df_fb, 'facebook', unified_tree)

    print("Mapping Google Shopping categories...")
    google_mapped = builder.map_original_to_unified(df_google, 'google', unified_tree)

    # Combine all mappings
    all_mapped = amazon_mapped + fb_mapped + google_mapped

    # Create output DataFrames
    df_full = pd.DataFrame(all_mapped)

    # Save unified_taxonomy_full.csv
    output_full = '/root/output/unified_taxonomy_full.csv'
    df_full.to_csv(output_full, index=False)
    print(f"\nSaved {output_full} with {len(df_full)} rows")

    # Extract all unique paths for hierarchy
    all_paths = builder.extract_all_paths(unified_tree)

    # Create hierarchy DataFrame
    hierarchy_data = []
    for path in all_paths:
        while len(path) < 5:
            path.append('')

        hierarchy_data.append({
            'unified_level_1': path[0] if len(path) > 0 else '',
            'unified_level_2': path[1] if len(path) > 1 else '',
            'unified_level_3': path[2] if len(path) > 2 else '',
            'unified_level_4': path[3] if len(path) > 3 else '',
            'unified_level_5': path[4] if len(path) > 4 else ''
        })

    df_hierarchy = pd.DataFrame(hierarchy_data).drop_duplicates()

    # Save unified_taxonomy_hierarchy.csv
    output_hierarchy = '/root/output/unified_taxonomy_hierarchy.csv'
    df_hierarchy.to_csv(output_hierarchy, index=False)
    print(f"Saved {output_hierarchy} with {len(df_hierarchy)} rows")

    # Print statistics
    print("\n=== Statistics ===")
    print(f"Total mapped categories: {len(all_mapped)}")
    print(f"By source:")
    print(f"  Amazon: {len(amazon_mapped)}")
    print(f"  Facebook: {len(fb_mapped)}")
    print(f"  Google: {len(google_mapped)}")
    print(f"\nUnified taxonomy levels:")
    print(f"  Level 1: {df_hierarchy['unified_level_1'].nunique()} categories")
    print(f"  Level 2: {df_hierarchy[df_hierarchy['unified_level_2'] != '']['unified_level_2'].nunique()} categories")
    print(f"  Level 3: {df_hierarchy[df_hierarchy['unified_level_3'] != '']['unified_level_3'].nunique()} categories")
    print(f"  Level 4: {df_hierarchy[df_hierarchy['unified_level_4'] != '']['unified_level_4'].nunique()} categories")
    print(f"  Level 5: {df_hierarchy[df_hierarchy['unified_level_5'] != '']['unified_level_5'].nunique()} categories")

    print("\n=== Completed Successfully ===")


if __name__ == '__main__':
    main()

