        level1_cats = [cat.split(':', 1)[1] for cat in self.category_counts.keys() if cat.startswith('L0:')]
        print(f"Found {len(level1_cats)} level 1 categories before clustering")

        level1_clusters = self.cluster_similar_categories(level1_cats, max_clusters=15)
        print(f"Created {len(level1_clusters)} level 1 clusters")

        for l1_rep, l1_members in level1_clusters.items():
            l1_name = self.generate_representative_name(l1_members)
            unified_tree[l1_name] = {'members': l1_members, 'children': {}}

            # Level 2: Subcategories under each L1
            level2_cats = set()
            for l1_member in l1_members:
                # Find all L2 categories that appear after this L1
                for cat_key in self.category_counts.keys():
                    if cat_key.startswith('L1:'):
                        level2_cats.add(cat_key.split(':', 1)[1])

            if level2_cats:
                level2_clusters = self.cluster_similar_categories(list(level2_cats), max_clusters=20)

                for l2_rep, l2_members in level2_clusters.items():
                    l2_name = self.generate_representative_name(l2_members, l1_name)

                    # Ensure distinct from siblings
                    sibling_names = list(unified_tree[l1_name]['children'].keys())
                    is_distinct = True
                    for sibling in sibling_names:
                        if self.normalizer.word_overlap(l2_name, sibling) > 0.3:
                            is_distinct = False
                            break

                    if not is_distinct:
                        # Modify name to be more distinct
                        l2_name = l2_rep

                    unified_tree[l1_name]['children'][l2_name] = {'members': l2_members, 'children': {}}

                    # Level 3
                    level3_cats = set()
                    for cat_key in self.category_counts.keys():
                        if cat_key.startswith('L2:'):
                            level3_cats.add(cat_key.split(':', 1)[1])

                    if level3_cats:
                        level3_clusters = self.cluster_similar_categories(list(level3_cats), max_clusters=20)

                        for l3_rep, l3_members in list(level3_clusters.items())[:20]:
                            l3_name = self.generate_representative_name(l3_members, l2_name)
                            unified_tree[l1_name]['children'][l2_name]['children'][l3_name] = {
                                'members': l3_members, 'children': {}
                            }

                            # Level 4
                            level4_cats = set()
                            for cat_key in self.category_counts.keys():
                                if cat_key.startswith('L3:'):
                                    level4_cats.add(cat_key.split(':', 1)[1])

                            if level4_cats:
                                level4_clusters = self.cluster_similar_categories(list(level4_cats), max_clusters=20)

                                for l4_rep, l4_members in list(level4_clusters.items())[:20]:
                                    l4_name = self.generate_representative_name(l4_members, l3_name)
                                    unified_tree[l1_name]['children'][l2_name]['children'][l3_name]['children'][l4_name] = {
                                        'members': l4_members, 'children': {}
                                    }

                                    # Level 5
                                    level5_cats = set()
                                    for cat_key in self.category_counts.keys():
                                        if cat_key.startswith('L4:'):
                                            level5_cats.add(cat_key.split(':', 1)[1])

                                    if level5_cats:
                                        level5_clusters = self.cluster_similar_categories(list(level5_cats), max_clusters=20)

                                        for l5_rep, l5_members in list(level5_clusters.items())[:20]:
                                            l5_name = self.generate_representative_name(l5_members, l4_name)
                                            unified_tree[l1_name]['children'][l2_name]['children'][l3_name]['children'][l4_name]['children'][l5_name] = {
                                                'members': l5_members
                                            }

        return unified_tree

    def map_original_to_unified(self, df: pd.DataFrame, source: str, unified_tree: Dict) -> List[Dict]:
        """Map original categories to unified taxonomy"""
        results = []

        for _, row in df.iterrows():
            original_path = row['category_path']
            parts = self.parse_category_path(original_path)

            if not parts:
                continue

            # Find best match in unified tree
            unified_levels = ['', '', '', '', '']

            # Match L1
            best_l1 = self.find_best_match(parts[0] if len(parts) > 0 else '', unified_tree)
            if best_l1:
                unified_levels[0] = best_l1

                # Match L2
                if len(parts) > 1 and best_l1 in unified_tree:
                    best_l2 = self.find_best_match(parts[1], unified_tree[best_l1].get('children', {}))
                    if best_l2:
                        unified_levels[1] = best_l2

                        # Match L3
                        if len(parts) > 2 and best_l2 in unified_tree[best_l1]['children']:
                            best_l3 = self.find_best_match(parts[2], unified_tree[best_l1]['children'][best_l2].get('children', {}))
                            if best_l3:
                                unified_levels[2] = best_l3

                                # Match L4
                                if len(parts) > 3 and best_l3 in unified_tree[best_l1]['children'][best_l2]['children']:
                                    best_l4 = self.find_best_match(parts[3], unified_tree[best_l1]['children'][best_l2]['children'][best_l3].get('children', {}))
                                    if best_l4:
                                        unified_levels[3] = best_l4

                                        # Match L5
                                        if len(parts) > 4 and best_l4 in unified_tree[best_l1]['children'][best_l2]['children'][best_l3]['children']:
                                            best_l5 = self.find_best_match(parts[4], unified_tree[best_l1]['children'][best_l2]['children'][best_l3]['children'][best_l4].get('children', {}))
                                            if best_l5:
                                                unified_levels[4] = best_l5

            depth = sum(1 for level in unified_levels if level)

            results.append({
                'source': source,
                'category_path': original_path,
                'depth': depth,
                'unified_level_1': unified_levels[0],
                'unified_level_2': unified_levels[1],
                'unified_level_3': unified_levels[2],
                'unified_level_4': unified_levels[3],
                'unified_level_5': unified_levels[4]
            })

        return results

    def find_best_match(self, category: str, candidates: Dict) -> str:
        """Find best matching category in candidates"""
        if not candidates:
            return ''

        if not category:
            return list(candidates.keys())[0] if candidates else ''

        best_match = None
        best_score = 0

        for candidate_name, candidate_data in candidates.items():
            # Check if category is in members
            if isinstance(candidate_data, dict) and 'members' in candidate_data:
                if category in candidate_data['members']:
                    return candidate_name

                # Check similarity with members
                for member in candidate_data['members']:
                    score = self.normalizer.word_overlap(category, member)
                    if score > best_score:
                        best_score = score
                        best_match = candidate_name

            # Also check similarity with candidate name itself
            score = self.normalizer.word_overlap(category, candidate_name)
            if score > best_score:
                best_score = score
                best_match = candidate_name

        return best_match if best_match else (list(candidates.keys())[0] if candidates else '')

    def extract_all_paths(self, tree: Dict, current_path: List[str] = None) -> List[List[str]]:
        """Extract all paths from tree"""
        if current_path is None:
            current_path = []

        paths = []

        for key, value in tree.items():
            new_path = current_path + [key]

            if isinstance(value, dict):
                if 'children' in value and value['children']:
                    # Recurse into children
                    paths.extend(self.extract_all_paths(value['children'], new_path))
                else:
                    # Leaf node
                    paths.append(new_path)
            else:
                paths.append(new_path)

        return paths


